# OWNER: (shared)   ROLE: coordinator (model with reasoning; no browser of its own)
# NEEDS: every analyst's results   WRITES: results["gaps"], follow-up evidence through the scrapers' sites
"""Decides what the scrapers collect next, so the run ends COLLECT with the data the bid needs instead of with what
the first pass happened to save.

While the first pass runs, the coordinator watches the board. As soon as a site's first pass and its analysis are done,
code lists the GAPS on that site: concrete facts the bid needs that no saved page holds (a position without a
matching material, a material without status / price scales / stock, a commercial key from the Q&A without its mail,
a usable-travel requirement without its technical release, no discount approval, ...). The model (with reasoning) turns
the gaps into a few focused jobs, one browser agent each, grouping what one agent can do in one go and skipping gaps the
saved pages show do not exist. Jobs run at once, in the site's browser (main tab when free, new tabs otherwise). After
each job the affected analyses run again on the new pages, which may reveal the next gaps.

No gap is worked on twice, every job states exactly what to read (so no two agents collect the same thing), and a page
another agent already saved is not opened again (read_page returns the saved text). Follow-ups stop when nothing is
missing, nothing new can be tried, or the collect time is used up.
"""
import asyncio
import json

from agents import analyze_discount, analyze_materials, analyze_quantities, analyze_requirements
from agents.compute_bid import INPUTS, compute, position_keys, valid_condition
from swarm import Agent, Phase, register, timeline
from swarm.extract import pages
from swarm.normalize import norm_ref, to_datetime
from swarm.scraper import run_job

ROUND_MIN_S = 100        # a follow-up job needs at least this much collect time
JOB_STEPS = 16
MAX_JOBS = 6             # per planning call
MAX_JOBS_PER_ROLE = 3
MAX_RUNNING_PER_ROLE = 2  # follow-up browses at once on one site (each is a tab of that site's browser)
ANALYSIS_S = 60          # jobs stop this long before collect ends, so the analyses can still run on their pages
SETTLE_S = 45           # a site whose analysis has not finished this long after its first pass is treated as done
PLAN_S = 60             # a planning call longer than this is dropped: the gaps become jobs as they are
MAIL_EARLY_S = 30        # mail gaps may start this long after the mail index pass was analysed (topic searches go on)
REPLAN_S = 45            # an unchanged set of open gaps is offered to the planner again only after this long

READY = {"tender": ("done.tender", "tender_final"), "spec": ("done.spec", "requirements_final"),
         "erp": ("done.erp", "materials"), "mail": ("done.mail", "mail_final")}

KEY_SECTIONS = {"konditionsgruppe": ("condition_rules", "condition rules (Konditionsregeln)"),
                "packaging_tariff": ("packaging_tariffs", "packaging tariff"),
                "delivery_key": ("delivery_commitments", "delivery commitment"),
                "setup_pool": ("setup_pools", "setup pool fee"),
                "bonus_plan": ("project_bonus", "project bonus bands")}

SYSTEM = """You coordinate browser agents that collect data for a priced bid. Each site has a scraper agent that already
did a first pass. You get the GAPS (facts the bid still needs), what each site holds, and the topics already saved.
Write follow-up jobs: one job = one browser agent on one site, a few sentences: what to open/search and what to
read_page with which topic label (e.g. 'erp prices <material>'). Put gaps one agent can do in one go into one job (at
most 3 gaps per job); separate jobs run in parallel. Name exact identifiers (material numbers, keys, references).
Skip an optional gap only with a direct quote from observed page evidence explicitly showing the data does not exist
(e.g. no Q&A at all). A topic label or scraper summary is not absence evidence. Never skip missing tender positions
or specification requirements. Never ask for
a page already saved unless it lacked the needed part (then say which part: e.g. open the quantity-scale register).
Reply JSON: {"jobs": [{"role": "tender|spec|erp|mail", "gaps": ["gap id", ...], "job": "..."}],
"skipped": [{"id": "gap id", "source": "observed page URL", "quote": "exact absence evidence"}]}"""

SITES = {"tender": "tender portal: tender overview, documents (bill of quantities), bidder Q&A",
         "spec": "buyer's portal: technical specification revisions and requirement tables",
         "erp": "our ERP: material search help, material records (technical data, status, lead times), price "
                "conditions with quantity scales, stock per storage location",
         "mail": "our webmail: approvals and release mails (discount, condition rules, technical release, packaging, "
                 "delivery, setup pools, project bonus, FX, price indices)"}


def _attrs(req: dict) -> str:
    return ", ".join(f"{k} {req.get(k)}" for k in ("bore", "stroke", "stroke_kind", "pressure", "mounting",
                                                     "certification") if req.get(k))


def find_gaps(board, ready: set[str], saved_topics: dict[str, list[str]]) -> list[dict]:
    """The facts the bid still needs, per site, from the results of the analyses that are ready. Plain code."""
    gaps: dict[str, dict] = {}

    def gap(role: str, gid: str, need: str) -> None:
        if role in ready:
            gaps.setdefault(gid, {"id": gid, "role": role, "need": need})

    brief = board.get("brief") or {}
    tender = board.get("tender") or {}
    positions = tender.get("positions") or []
    requirements = board.get("requirements") or {}
    materials = board.get("materials") or {}
    erp = board.get("erp") or {}
    mail = board.get("mail") or {}
    erp_materials = {norm_ref(k): v for k, v in (erp.get("materials") or {}).items()}
    scenario = to_datetime(brief.get("scenario_date"))
    if "tender" in ready and not positions:
        gap("tender", "tender positions", "bill of quantities / position overview: positions, quantities, units, "
                                          "requirement references")
    if positions and not tender.get("clarifications"):
        gap("tender", "tender q&a", "bidder Q&A of the tender, all pages (if the tender has any)")
    if (board.get("discount") or {}).get("source") in ("no valid approval found", "latest approval invalid"):
        gap("mail", "mail discount", f"sales director's discount approval for {brief.get('tender_reference')} "
                                     "(inbox and archive)")
    clarifications = tender.get("clarifications") or []
    for p in positions:
        pos = str(p.get("position")).strip()
        ref = p.get("requirement_ref")
        req = next((v for k, v in requirements.items() if norm_ref(k) == norm_ref(ref)), None)
        if req is None:
            gap("spec", f"spec requirement {ref}", f"requirement {ref} of the CURRENT specification revision (bore, "
                                                   "stroke, pressure, mounting, certification, catalogue group)")
            continue
        group = req.get("kataloggruppe") or ""
        if req.get("stroke_kind") == "usable":
            releases = mail.get("technical_release") or {}
            if not releases:
                gap("mail", "mail technical release",
                    f"technical release mail with end reserves per stroke end (revision {req.get('revision')}"
                    f"{', key ' + str(req.get('reserve_key')) if req.get('reserve_key') else ''})")
        m = materials.get(pos) or {}
        for key, value in position_keys(clarifications, pos)["keys"].items():
            section, label = KEY_SECTIONS.get(key, (None, None))
            if section and norm_ref(value) not in {norm_ref(k) for k in (mail.get(section) or {})}:
                article = f" (or by material number {m['material']})" if section == "delivery_commitments" and \
                    m.get("material") else ""
                gap("mail", f"mail {section} {norm_ref(value)}", f"{label} mail for key {value}{article}")
        if not m:
            gap("erp", f"erp search {group or ref}", f"Find materials for requirement {ref}: {_attrs(req)}")
            continue
        mat = m.get("material")
        if not mat:
            searched = any(norm_ref(group) and norm_ref(group) in norm_ref(t) for t in saved_topics.get("erp", []))
            in_group = [v["material"] for v in erp_materials.values()
                        if norm_ref(v.get("kataloggruppe")) == norm_ref(group)] if group else []
            if not searched and not in_group:
                gap("erp", f"erp search {group or ref}", f"search result list of catalogue group {group} "
                                                         f"(requirement {ref}: {_attrs(req)})")
            elif m.get("reason") == "only blocked matches":
                gap("erp", f"erp status {group or ref}", f"status (active/blocked, from record and status legend) of "
                                                         f"{[c['material'] for c in m.get('candidates') or []]}: all "
                                                         f"read as blocked for requirement {ref}")
            else:
                gap("erp", f"erp records {group or ref}", f"record pages (technical data incl. stroke and "
                                                          f"certification, status) of materials {in_group or 'of group ' + group}: "
                                                          f"none matched requirement {ref} ({_attrs(req)}) on the pages "
                                                          "read")
            continue
        info = erp_materials.get(norm_ref(mat)) or {}
        missing = [a for a in m.get("unverified") or [] if a != "end reserve"]   # that one is the release mail's
        if info.get("lead_time_production_weeks") in (None, ""):
            missing.append("lead times")
        if position_keys(clarifications, pos)["keys"].get("packaging_tariff") and not info.get("pieces_per_carton"):
            missing.append("pieces per carton")
        if missing:
            gap("erp", f"erp record {norm_ref(mat)}", f"record of material {mat} (all tabs, status legend): "
                                                      f"{', '.join(dict.fromkeys(missing))} not read")
        conds = [c for c in erp.get("conditions") or [] if norm_ref(c.get("material")) == norm_ref(mat)]
        cond = valid_condition(conds, mat, scenario)
        if not conds:
            gap("erp", f"erp prices {norm_ref(mat)}", f"price condition records of material {mat} with quantity scales")
        elif cond is None:
            gap("erp", f"erp prices {norm_ref(mat)}", f"price condition of material {mat} valid on "
                                                      f"{brief.get('scenario_date')} (read: "
                                                      f"{[(c.get('valid_from'), c.get('valid_to')) for c in conds]}; "
                                                      "other condition records/periods)")
        elif not cond.get("scales"):
            gap("erp", f"erp prices {norm_ref(mat)}", f"quantity scales of the valid price condition of {mat} (open "
                                                      "the quantity-scale register)")
        elif norm_ref(cond.get("currency") or "EUR") != "EUR" and \
                norm_ref(cond.get("currency")) not in {norm_ref(k) for k in (mail.get("fx_fixing") or {})}:
            gap("mail", f"mail fx {norm_ref(cond.get('currency'))}", f"FX fixing mail for {cond.get('currency')} "
                                                                     f"(key {cond.get('fx_key')})")
        if norm_ref(mat) not in {norm_ref(k) for k in (erp.get("stock") or {})}:
            gap("erp", f"erp stock {norm_ref(mat)}", f"stock of material {mat} at storage-location level")
        index = info.get("metal_index")
        if index and norm_ref(index) not in {norm_ref(k) for k in (mail.get("price_indices") or {})}:
            gap("mail", f"mail price index {norm_ref(index)}", f"metal price index mail for {index} valid on "
                                                               f"{brief.get('scenario_date')}")
    # What the calculation itself still misses (a condition without price unit, a pool fee, a carton size, ...):
    # checks above establish that a topic exists; these establish that the value the bid needs is usable.
    for dep in dependency_gaps(board):
        if dep["role"] not in ready:
            continue
        have = gaps.get(dep["id"])
        if have is None:
            gaps[dep["id"]] = {"id": dep["id"], "role": dep["role"], "need": dep["need"]}
        elif dep["need"] not in have["need"]:
            have["need"] += f"; calculation needs: {dep['need']}"
    return list(gaps.values())


def direct_jobs(gaps: list[dict]) -> list[dict]:
    """Jobs straight from the gap texts (at most 3 gaps per job), for when the planning call fails or is too slow."""
    jobs, per_role = [], {}
    for g in gaps:
        per_role.setdefault(g["role"], []).append(g)
    for role, items in per_role.items():
        for i in range(0, min(len(items), 3 * MAX_JOBS_PER_ROLE), 3):
            chunk = items[i:i + 3]
            jobs.append({"role": role, "gaps": [g["id"] for g in chunk],
                         "job": "Find and read_page (topic naming the identifier): " +
                                "; ".join(g["need"] for g in chunk) + ". Then done."})
    return jobs[:MAX_JOBS]


def dependency_gaps(board) -> list[dict]:
    """The bid calculation's open dependencies on the sites (not the ones on other positions), with the positions
    each one blocks. Material matching is left to find_gaps' search/record gaps (more specific)."""
    try:
        bid = compute({n: board.get(n) for n in INPUTS})
    except Exception:  # noqa: BLE001 - a half-collected board: the gaps above still apply
        return []
    return [{"id": d["id"], "role": d["role"], "need": f"{d['need']} (positions {', '.join(d['positions'])})"}
            for d in (bid.get("dependencies") or {}).values()
            if d["role"] in READY and d.get("kind") != "material"]


async def refresh(ctx, roles: set[str]) -> None:
    """Run the analyses that depend on new pages of `roles` again (each failure is only logged)."""
    steps = []
    if "tender" in roles:
        steps += [analyze_quantities.refresh]
    if roles & {"tender", "spec"} and pages(ctx, "spec"):
        steps += [analyze_requirements.refresh]
    if "mail" in roles:
        steps += [analyze_discount.refresh]
    if pages(ctx, "erp"):
        steps += [analyze_materials.refresh]
    for step in steps:
        try:
            await step(ctx)
        except Exception as error:
            ctx.board.error("CollectionCoordinator", f"refresh {step.__module__}: {error}")


@register
class CollectionCoordinator(Agent):
    phase = Phase.COLLECT

    def __init__(self, ctx):
        super().__init__(ctx)
        self.tried: set[str] = set()
        self.attempts: dict[str, int] = {}
        self.running: dict[asyncio.Task, str] = {}      # follow-up job -> its site role
        self.history: list[dict] = []
        self.first_pass_end: dict[str, float] = {}
        self.mail_core_at: float | None = None
        self.last_offer: frozenset = frozenset()
        self.last_plan_at = -1e9

    def ready(self) -> set[str]:
        """Sites whose first pass and analysis are done (gaps can be judged). The mail counts once its index pass
        was analysed for MAIL_EARLY_S: key-specific gaps (a packaging tariff, a pool fee) need not wait for the
        generic topic searches."""
        out = {role for role, keys in READY.items() if all(self.ctx.board.get(k) is not None for k in keys)}
        if self.ctx.board.get("done.mail_core") is not None and self.ctx.board.get("mail") is not None:
            self.mail_core_at = self.mail_core_at if self.mail_core_at is not None else self.ctx.elapsed()
            if self.ctx.elapsed() - self.mail_core_at >= MAIL_EARLY_S:
                out.add("mail")
        return out

    def settled(self) -> set[str]:
        """Ready sites, plus sites whose analysis has not finished SETTLE_S after the first pass (it failed)."""
        now = self.ctx.elapsed()
        for role, (done_key, _) in READY.items():
            if self.ctx.board.get(done_key) is not None:
                self.first_pass_end.setdefault(role, now)
        return self.ready() | {r for r, t in self.first_pass_end.items() if now - t > SETTLE_S}

    def saved_topics(self) -> dict[str, list[str]]:
        return {role: sorted({str(e.data.get("topic", "")).lower() for e in pages(self.ctx, role)} - {""})
                for role in READY}

    async def plan(self, gaps: list[dict]) -> list[dict]:
        board = self.ctx.board
        summaries = {k: str(v)[:600] for k, v in board.results.items() if k.endswith(".summary")}
        prompt = {"tender_reference": (board.get("brief") or {}).get("tender_reference"),
                  "scenario_date": (board.get("brief") or {}).get("scenario_date"),
                  "gaps": gaps, "sites": {r: SITES[r] for r in {g["role"] for g in gaps}},
                  "saved_topics": self.saved_topics(), "first_pass_summaries": summaries,
                  "observed_pages": [{"source": e.source or e.data.get("url"), "text": e.data.get("text", "")[:1800]}
                                     for role in {g["role"] for g in gaps} for e in pages(self.ctx, role)[-3:]],
                  "earlier_followups": self.history[-8:], "site_tips": board.get("tips") or {}}
        reply = await self.ctx.llm.ask_json(SYSTEM, json.dumps(prompt, ensure_ascii=False, default=str), think=True)
        jobs, per_role = [], {}
        known = {g["id"]: g for g in gaps}
        for j in (reply or {}).get("jobs") or []:
            role = j.get("role")
            ids = [i for i in j.get("gaps") or [] if i in known and known[i]["role"] == role]
            if role not in READY or not ids or not str(j.get("job") or "").strip():
                continue
            if per_role.get(role, 0) >= MAX_JOBS_PER_ROLE or len(jobs) >= MAX_JOBS:
                continue
            per_role[role] = per_role.get(role, 0) + 1
            jobs.append({"role": role, "gaps": ids, "job": str(j["job"]).strip()})
        skipped = []
        for item in (reply or {}).get("skipped") or []:
            if not isinstance(item, dict) or item.get("id") not in known:
                continue
            gid = item["id"]
            if gid == "tender positions" or gid.startswith("spec requirement "):
                continue
            quote = " ".join(str(item.get("quote") or "").split())
            if len(quote) >= 12 and any(
                item.get("source") == (e.source or e.data.get("url"))
                and quote in " ".join(str(e.data.get("text") or "").split())
                for e in pages(self.ctx, known[gid]["role"])
            ):
                skipped.append(gid)
        if skipped:
            self.log.info("gaps skipped by the model: %s", skipped)
        self.tried |= set(skipped)
        return jobs

    async def work(self, job: dict) -> None:
        try:
            with timeline.span("followup", f"{job['role']} {','.join(job['gaps'])[:60]}"):
                out = await run_job(self.ctx, job["role"], job["job"], max_steps=JOB_STEPS, stop_extra=ANALYSIS_S)
            self.history.append({"role": job["role"], "gaps": job["gaps"], "done": out.get("done"),
                                 "summary": str(out.get("summary"))[:300]})
            self.log.info("follow-up %s %s done=%s: %s", job["role"], job["gaps"], out.get("done"),
                          str(out.get("summary"))[:200])
        except Exception as error:
            self.ctx.board.error(self.name, f"follow-up {job['gaps']}: {error}")
            self.tried.difference_update(job["gaps"])
        if not locals().get("out", {}).get("done"):
            self.tried.difference_update(job["gaps"])
        await refresh(self.ctx, {job["role"]})

    async def run(self) -> None:
        try:
            while True:
                ready = self.settled()
                if self.ctx.time_left() > ROUND_MIN_S:
                    gaps = [g for g in find_gaps(self.ctx.board, ready, self.saved_topics()) if g["id"] not in self.tried and self.attempts.get(g["id"], 0) < 2]
                    # a site with follow-ups running still takes new, different gaps while it has a free slot
                    busy = {r: list(self.running.values()).count(r) for r in set(self.running.values())}
                    gaps = [g for g in gaps if busy.get(g["role"], 0) < MAX_RUNNING_PER_ROLE]
                    offer = frozenset(g["id"] for g in gaps)
                    if gaps and offer == self.last_offer and self.ctx.elapsed() - self.last_plan_at < REPLAN_S:
                        gaps = []                 # the same gaps were just planned (model skipped them): not again yet
                    if gaps:
                        self.last_offer, self.last_plan_at = offer, self.ctx.elapsed()
                        self.log.info("gaps: %s", [g["id"] for g in gaps])
                        try:
                            jobs = await asyncio.wait_for(self.plan(gaps), PLAN_S)
                        except (Exception, asyncio.TimeoutError) as error:
                            self.log.warning("planning failed (%s): jobs straight from the gaps",
                                             type(error).__name__)
                            jobs = direct_jobs(gaps)
                        for job in jobs:
                            if busy.get(job["role"], 0) >= MAX_RUNNING_PER_ROLE:
                                continue                  # its gaps stay open for the next round
                            busy[job["role"]] = busy.get(job["role"], 0) + 1
                            for gid in job["gaps"]:
                                self.attempts[gid] = self.attempts.get(gid, 0) + 1
                            self.tried.update(job["gaps"])
                            task = asyncio.create_task(self.work(job))
                            self.running[task] = job["role"]
                            task.add_done_callback(lambda t: self.running.pop(t, None))
                all_done = self.settled() == set(READY)
                if self.running:
                    await asyncio.wait(list(self.running), timeout=5)
                    continue
                pending = [g for g in find_gaps(self.ctx.board, ready, self.saved_topics())
                           if g["id"] not in self.tried and self.attempts.get(g["id"], 0) < 2]
                if (all_done and not pending) or self.ctx.time_left() <= ROUND_MIN_S:
                    gaps = find_gaps(self.ctx.board, set(READY), self.saved_topics())
                    await self.ctx.board.set("gaps", gaps)
                    self.log.info("collect complete; open gaps: %s", [g["id"] for g in gaps])
                    return
                await asyncio.sleep(5)
        finally:
            tasks = list(self.running)
            for task in tasks:
                task.cancel()
            await asyncio.gather(*tasks, return_exceptions=True)
# OWNER: (name)   ROLE: scraper   SITE: our ERP (role "erp")
"""Looks up ERP candidates for the required cylinders, saved as page evidence ("erp.page").

The ERP only lists records for narrow searches, so the work starts once the requirements are known
(results["requirements"], from agents/analyze_requirements.py). While waiting, the main tab of browser 2 logs in and
passes the ERP's gates. Then the work runs as small jobs on up to ERP_TABS tabs of browser 2 (they share the login):

1. search: one job per catalogue group (Kataloggruppe): search it, save the result list. Nothing else.
2. As soon as a list is saved, the materials on it that fit a requirement (agents/analyze_materials.search_candidates:
   bore, pressure, mounting, certification equal where shown; stroke equal or covering the usable travel) become three
   jobs each, run in parallel: record (all tabs incl. status and lead times), prices (condition records with the
   quantity-scale register open) and stock (storage-location level).
   A material whose record turns out blocked gets no price/stock job (they wait behind the record jobs).

Small jobs finish inside their step budget (one big job per group used to run out of steps before prices and stock),
and no step is spent on materials the list already rules out. results["done.erp"] is set when the queue is empty.

Scheduling: the next job is chosen when a tab gets free, by what it adds to a submit-ready answer (`priority`): first
focused re-reads of something the bid calculation still misses, then prices and stock of materials that already match
a position (they finish that position), then searches and the best candidate record per requirement, then further
candidates; records of candidates for positions that already have a verified active match come last. A tab never
waits for its page's extraction: that runs in the background and queues the follow-up jobs when it is done. After a
material's prices / stock / record were read, the calculator's open dependencies for it (a condition without its price
unit, scales, stock, lead times, carton size, ...) queue one focused re-read naming exactly what is missing.
"""
import os
import asyncio
import itertools

from agents.analyze_materials import extract_erp, merge_materials, search_candidates
from swarm import Phase, register, timeline  # noqa: F401
from swarm.browser_agent import Tab
from swarm.blackboard import Evidence
from swarm.normalize import norm_ref
from swarm.scraper import SiteScraper
from swarm.sites import site_for

ANALYSIS_TIME_S = 60    # what the material matcher needs after the last ERP page
# parallel ERP jobs (main tab included). 8 once stalled every sandbox browser at once; A/B on 2026-10-11 (same code):
# 6 tabs 17 ERP jobs / 4 positions priced / 10 failed browses (run_1efbfc7e6d2895e0) vs 4 tabs 12 / 1 / 16
# (run_db181692d8232b97); 4 tabs in run_7a11d3a90d55e1ce: 15 / 3. ERP throughput is the collection bottleneck.
ERP_TABS = int(os.environ.get("SWARM_ERP_TABS", "6"))

HINTS = ("Adapt to the observed software; these are possible patterns, not requirements. ERP habits: SAP-style transaction codes (start page / menu lists transactions for material display, stock "
         "overview, price conditions); system notice or access gate after login (copy displayed number exactly - "
         "read_page shows numbers drawn on canvas -, confirm, continue; slider/robot gate passes with ONE fill_form: "
         "slider = its maximum (e.g. 100), robot checkbox = true, then the number and confirmation checkbox, then_click "
         "continue button); material search help (F4) lists results only for narrow search term; records with several "
         "tabs/registers (basic data, technical data, planning/status with lead times; condition header and quantity "
         "scales; stock per plant and per storage location); status codes explained in legend or tooltip; short session "
         "timeout - log in again when login page appears. Save steps: once you see the links of a record's "
         "tabs/registers, read all with ONE read_page(urls=[...]) using each link's exact href as shown on the page "
         "as listed in read_page's text (never guess, translate or shorten URL parameters: guessed tab URLs return 404; "
         "find_elements does not show hrefs); transactions often take the material number "
         "directly in their entry field.")

FOLLOWUP, FINISH, SEARCH, BEST_RECORD, RECORD, SPECULATIVE, COVERED = 0, 1, 2, 2, 3, 4, 6
MAX_FOCUSED = 1          # focused re-reads per (job kind, material) after the first read


def work_items(requirements: dict) -> list[dict]:
    """One item per catalogue group (or per requirement when no group is given), with the attributes to check."""
    items: dict[str, dict] = {}
    for ref, req in (requirements or {}).items():
        group = (req.get("kataloggruppe") or "").strip()
        key = group or f"req:{ref}"
        item = items.setdefault(key, {"group": group, "requirements": []})
        item["requirements"].append({k: req.get(k) for k in ("bore", "stroke", "stroke_kind", "pressure", "mounting",
                                                              "certification")} | {"ref": ref})
    return list(items.values())


def describe(item: dict) -> str:
    return "\n".join(f"- requirement {r['ref']}: bore {r['bore']} mm, stroke {r['stroke']} mm"
                     f"{' (usable travel; nominal stroke will be longer)' if r.get('stroke_kind') == 'usable' else ''}, "
                     f"pressure {r['pressure']} bar, mounting {r['mounting']}, certification {r['certification']}"
                     for r in item["requirements"])


def search_goal(item: dict) -> str:
    what = f"catalogue group (Kataloggruppe) {item['group']}" if item["group"] else "these technical attributes"
    term = item["group"] or "the attributes"
    return (f"Find our ERP materials for {what}. Required:\n{describe(item)}\n"
            "1. Log in if needed, open material search (search help of material display transaction).\n"
            f"2. Search {term}; read_page the result list with topic 'erp search {item['group']}' (all result pages "
            "via next_page_link).\n"
            "3. done, listing the materials of the list with their attributes. Do NOT open records (other agents do).")


def material_goal(job: str, material: str, item: dict, missing: str = "") -> str:
    group = f" (catalogue group {item['group']})" if item.get("group") else ""
    find = (f"Open material {material}{group}: type the number into the transaction's material field, or search "
            f"{item.get('group') or material} in its search help and click the row of {material}.")
    focus = (f"\nA previous read of it did NOT show: {missing}. Find exactly that (other tab/register/record, "
             "header vs. detail view, tooltip) and read_page the page that shows it.") if missing else ""
    if job == "record":
        return (f"{find}\nread_page EVERY tab/register of its record (basic data, technical data, planning/status with "
                f"lead times and status; status legend or tooltip too) with topic 'erp material {material}', in one "
                f"read_page(urls=[...]) when the tabs are links: read_page the open record first (its text lists each tab "
                f"link's href), then the other tabs by exactly those hrefs; never guess URLs, and don't use find_elements "
                f"for hrefs (it does not show them). Or click each tab and read_page it. done with status and lead "
                f"times.{focus}")
    if job == "prices":
        return (f"Price conditions of material {material}{group}: open the price condition display transaction for "
                f"it, open its quantity-scale register so every scale row shows, read_page with topic 'erp prices "
                f"{material}' (the header with validity, price unit and condition record number must be in the read "
                "too); several condition records (validity periods) -> read each one (next_page_link = exact "
                f"text of link to next record). done with validity periods, price unit and scale prices.{focus}")
    return (f"Stock of material {material}{group}: open the stock overview transaction for it, open storage-location "
            f"level so quantity per location and stock type shows, read_page with topic 'erp stock {material}'. done "
            f"with freely usable quantity per location.{focus}")


async def _items(ctx) -> list[dict]:
    requirements = await ctx.board.wait_for(key="requirements", timeout=max(1.0, ctx.time_left()))
    used = {str(p.get("requirement_ref") or "").strip().upper()
            for p in ((ctx.board.get("tender") or {}).get("positions") or [])}
    if used - {""}:                       # only requirements some position refers to
        requirements = {k: v for k, v in requirements.items() if k.strip().upper() in used} or requirements
    items = work_items(requirements)
    await ctx.board.set("erp.work_items", items)
    return items


@register
class ErpScraper(SiteScraper):
    role = "erp"
    browser = 2
    max_steps = 16
    hints = HINTS

    def __init__(self, ctx):
        super().__init__(ctx)
        self.jobs: list[tuple[int, tuple]] = []      # (insertion order, job); the next job is chosen when taken
        self.pending = 0                               # queued + running jobs + background extractions
        self.producer_done = False
        self.seen: set = set()
        self.focused: dict[tuple, int] = {}
        self.rank: dict[str, int] = {}                 # material -> its place among its search's candidates
        self._order = itertools.count()
        self.background: set[asyncio.Task] = set()

    # ---- queue ----------------------------------------------------------------------------------------------------
    def add(self, job: tuple, force: bool = False) -> bool:
        key = job[:2] if job[0] != "search" else ("search", job[1]["group"], repr(job[1]["requirements"]))
        if key in self.seen and not force:
            return False
        self.seen.add(key)
        self.pending += 1
        self.jobs.append((next(self._order), job))
        return True

    def matched(self) -> dict[str, list[str]]:
        """material -> positions it currently matches (verified active exact match)."""
        out: dict[str, list[str]] = {}
        for pos, m in (self.ctx.board.get("materials") or {}).items():
            if m.get("material") and not m.get("unverified"):
                out.setdefault(norm_ref(m["material"]), []).append(pos)
        return out

    def positions_of(self, item: dict) -> list[str]:
        refs = {norm_ref(r.get("ref")) for r in item.get("requirements") or []}
        return [str(p.get("position")) for p in (self.ctx.board.get("tender") or {}).get("positions") or []
                if norm_ref(p.get("requirement_ref")) in refs]

    def priority(self, job: tuple) -> int:
        """What the job adds to a submit-ready answer (lower first)."""
        kind = job[0]
        if kind == "search":
            return SEARCH
        material, item = job[1], job[2]
        matched = self.matched()
        if len(job) > 3 and job[3]:                    # focused re-read of something the calculation misses
            return FOLLOWUP
        if kind in ("prices", "stock"):
            return FINISH if norm_ref(material) in matched else SPECULATIVE
        positions = self.positions_of(item)
        covered = {p for ps in matched.values() for p in ps}
        if positions and all(p in covered for p in positions):
            return COVERED
        return BEST_RECORD if self.rank.get(norm_ref(material), 0) == 0 else RECORD

    def take(self) -> tuple | None:
        if not self.jobs:
            return None
        best = min(self.jobs, key=lambda j: (self.priority(j[1]), j[0]))
        self.jobs.remove(best)
        return best[1]

    def blocked(self, material: str) -> bool:
        """True if the material's record page (read meanwhile) says it is blocked: its prices and stock are not needed."""
        info = merge_materials(list(self.ctx.shared.get("erp.extracted", {}).values())).get(norm_ref(material)) or {}
        return info.get("is_active") is False

    # ---- jobs -----------------------------------------------------------------------------------------------------
    async def extract_job(self, out: dict) -> dict:
        evidence = []
        for record in out.get("records") or []:
            data = record.get("data") or {}
            text = data.get("text") or data.get("_observed_text")
            if text:
                evidence.append(Evidence("erp.page", self.site_id,
                    {**data, "text": text, "url": data.get("url") or record.get("source"),
                     "topic": data.get("topic") or record.get("kind", "")}))
        return await extract_erp(self.ctx, evidence=evidence)

    def spawn(self, coro) -> None:
        """Background work that may queue jobs: counted as pending so no worker quits while it runs."""
        self.pending += 1
        task = asyncio.ensure_future(coro)
        self.background.add(task)
        self.ctx.shared.setdefault("background", set()).add(task)

        def finished(t):
            self.pending -= 1
            self.background.discard(t)
            if not t.cancelled() and t.exception() is not None:
                self.ctx.board.error(self.name, f"extraction: {type(t.exception()).__name__}: {t.exception()}")
        task.add_done_callback(finished)

    async def after_search(self, item: dict, out: dict) -> None:
        found = search_candidates(await self.extract_job(out), item)
        self.log.info("search %s: candidates %s", item["group"], found)
        for i, material in enumerate(found):
            self.rank.setdefault(norm_ref(material), i)
            self.add(("record", material, item))

    async def after_material(self, kind: str, material: str, item: dict, out: dict) -> None:
        await self.extract_job(out)
        from agents import analyze_materials
        await analyze_materials.publish(self.ctx)            # the match (and so the priorities) follows at once
        if kind == "record" and not self.blocked(material):
            self.add(("prices", material, item))
            self.add(("stock", material, item))
        self.focus(kind, material, item)

    def missing_for(self, kind: str, material: str) -> str:
        """What the bid calculation still misses from this material's `kind` pages ('' if nothing / not matched)."""
        from agents.compute_bid import build_bid
        try:
            bid = build_bid(self.ctx)
        except Exception as error:  # noqa: BLE001
            self.log.debug("draft for focus failed: %s", error)
            return ""
        dep = (bid.get("dependencies") or {}).get(f"erp {kind} {norm_ref(material)}")
        return dep["need"] if dep else ""

    def focus(self, kind: str, material: str, item: dict) -> None:
        """One focused re-read when the calculation still misses something this kind of page should show."""
        if norm_ref(material) not in self.matched() or self.blocked(material):
            return
        missing = self.missing_for(kind, material)
        key = (kind, norm_ref(material))
        if missing and self.focused.get(key, 0) < MAX_FOCUSED:
            self.focused[key] = self.focused.get(key, 0) + 1
            self.log.info("%s %s still misses: %s -> focused re-read", kind, material, missing[:160])
            timeline.count("erp.focused")
            self.add((kind, material, item, missing), force=True)

    async def do(self, job: tuple, tab: Tab | None) -> None:
        extra = ANALYSIS_TIME_S
        if job[0] == "search":
            item = job[1]
            out = await self.browse_until_done(search_goal(item), attempts=2, tab=tab, max_steps=14, stop_extra=extra)
            self.spawn(self.after_search(item, out))
            return
        kind, material, item = job[:3]
        missing = job[3] if len(job) > 3 else ""
        if kind != "record" and self.blocked(material):
            self.log.info("%s %s skipped: material blocked", kind, material)
            return
        out = await self.browse_until_done(material_goal(kind, material, item, missing), attempts=2, tab=tab,
                                           max_steps=16, stop_extra=extra)
        self.spawn(self.after_material(kind, material, item, out))

    async def worker(self, tab: Tab | None) -> None:
        """Takes jobs until none is queued and no running job or extraction can add more (or time is up)."""
        try:
            while self.ctx.time_left() > 0:
                if self.ctx.time_left() <= ANALYSIS_TIME_S:
                    # too late for a new job now, but the live reserve may shrink again (e.g. the wizard warm-up
                    # finishing): wait instead of quitting (run_e38e6666df284e76 ended collection with time unused)
                    if self.pending <= 0 and self.producer_done and not self.jobs:
                        return
                    await asyncio.sleep(2)
                    continue
                job = self.take()
                if job is None:
                    if self.pending <= 0 and self.producer_done:
                        return
                    await asyncio.sleep(1.0)
                    continue
                label = f"{job[0]} {job[1] if job[0] != 'search' else job[1]['group']}"
                try:
                    with timeline.span("erp.job", label):
                        await self.do(job, tab)
                except Exception as error:
                    self.ctx.board.error(self.name, f"{label}: {error}")
                finally:
                    self.pending -= 1
        finally:
            if tab is not None:
                await tab.close()

    async def run(self) -> None:
        try:
            self.site_id = self.site_id or await site_for(self.ctx, self.role)
            if self.ctx.board.get("requirements") is None:      # use the wait: log in and pass the ERP's gates now
                await self.browse_until_done("Log in, accept cookies, pass any system notice or access gate, open "
                                             "material search help of material display transaction. Do NOT search "
                                             "yet. done once search form open.", attempts=1, max_steps=12)

            async def produce():
                try:
                    while self.ctx.time_left() > 0:
                        for item in await _items(self.ctx):
                            self.add(("search", item))
                        if self.ctx.board.get("requirements_final"):
                            return
                        await asyncio.sleep(2)
                finally:
                    self.producer_done = True
            async with asyncio.TaskGroup() as group:
                group.create_task(produce())
                group.create_task(self.worker(None))
                for _ in range(ERP_TABS - 1):
                    group.create_task(self.worker(Tab(self.browser)))
            if self.background:                       # the last extractions (time is up for new jobs)
                await asyncio.wait(set(self.background), timeout=max(1.0, self.ctx.time_left()))
        finally:
            await self.ctx.board.set("done.erp", True)
    classes = select(discover(), None if scored else env.get("SWARM_ONLY"))
    from swarm.browser_agent import _CHECKED, _HUNG_AT, _MAIN_TABS, _OWNERS, _OPENERS
    from swarm import guard
    for state in (_MAIN_TABS, _OWNERS, _OPENERS, _CHECKED, _HUNG_AT):
        state.clear()
    guard._DECISIONS.clear()
    guard._PENDING.clear()
    log.info("agents: %s", [c.__name__ for c in classes])
    heartbeat = asyncio.create_task(_heartbeat())
    try:
        await ctx.pool.prepare()
        for phase in Phase:
            agents = [c(ctx) for c in classes if c.phase == phase]
            if not agents:
                continue
            bound = phase != Phase.SUBMIT
            if phase not in ALWAYS and ctx.time_left() <= 0:
                log.warning("skipping phase %s: out of time", phase.name)
                continue
            log.info("phase %s: %s (%.0fs left)", phase.name, [a.name for a in agents], ctx.seconds_left())
            if phase == Phase.SUBMIT:
                timeline.mark("submit start", left=round(ctx.seconds_left()),
                              positions=len(((board.get("bid") or {}).get("answer") or {}).get("positions") or []))
            progress = asyncio.create_task(_progress(ctx))
            background = [asyncio.create_task(_run_agent(a, bound)) for a in agents if a.background]
            try:
                await asyncio.gather(*(_run_agent(a, bound) for a in agents if not a.background))
            finally:
                for running in background + [progress]:
                    running.cancel()
                await asyncio.gather(progress, *background, return_exceptions=True)
            if phase == Phase.COLLECT:
                timeline.mark("collect end", left=round(ctx.seconds_left()))
                tl.log_report()          # the platform ends the process right after the submission: report now too
                await _cancel_background(ctx)
                # Guard classification tasks are collection work too. None may survive into signing.
                pending = list(guard._TASKS)
                for t in pending:
                    t.cancel()
                await asyncio.gather(*pending, return_exceptions=True)
                from agents import analyze_discount, analyze_materials, analyze_quantities, analyze_requirements
                await analyze_quantities.publish(ctx)
                await analyze_requirements.publish(ctx)
                await analyze_discount.publish(ctx)
                await analyze_materials.publish(ctx)
                log.info("board after collect (%.0fs left): %s", ctx.seconds_left(), board_summary(board))
            if not scored:
                board.dump(BOARD_DUMP)
        log.info("model calls: %d tokens: %s errors: %d", ctx.llm.calls, ctx.llm.tokens, len(board.errors))
        if (task.get("submission") or {}).get("kind", "api") != "api":
            receipt = board.get("submission") or {}
            if not receipt.get("accepted"):
                raise RuntimeError("No confirmed portal receipt; the run did not verify submission"
                                   + (f" ({receipt['evidence']})" if receipt.get("evidence") else ""))
            log.info("portal acceptance confirmed: %s %s", receipt.get("reference"), receipt.get("evidence") or receipt.get("quote", ""))
            return None                      # a "site" submission was entered by the submitter agent
        answer = board.get("answer")
        if answer is None:
            raise RuntimeError("No schema-valid API answer was produced")
        return answer
    finally:
        heartbeat.cancel()
        pending = list(guard._TASKS)
        for t in pending:
            t.cancel()
        await asyncio.gather(*pending, return_exceptions=True)
        await _cancel_background(ctx)
        await ctx.pool.close()
        if ctx.llm._client is not None:
            await ctx.llm._client.close()
        try:
            tl.log_report()
            if not scored:
                tl.dump(TIMELINE_DUMP)
        except Exception as error:  # noqa: BLE001 - reporting must never fail a run
            log.debug("timeline report failed: %s", error)


async def _cancel_background(ctx) -> None:
    """Extraction tasks started by analysts in the background (they publish when done) end with collection."""
    tasks = [t for t in ctx.shared.get("background", set()) if not t.done()]
    for t in tasks:
        t.cancel()
    await asyncio.gather(*tasks, return_exceptions=True)
    def _lenient(cls, value):
        """A record whose facts came under another key, as a list, or with a non-text note failed validation and cost
        the agent a step (sandbox: '86 validation errors ... record'); keep the facts instead."""
        if not isinstance(value, dict):
            return value
        out = {k: value[k] for k in ("kind", "data", "source", "note") if k in value}
        extra = {k: v for k, v in value.items() if k not in out}
        data = out.get("data")
        if data is None:
            data = {}
        elif not isinstance(data, dict):
            data = {"value": data}
        out["data"] = {**extra, **data} if extra else data
        for key in ("kind", "source", "note"):
            if key in out and not isinstance(out[key], str):
                out[key] = json.dumps(out[key], ensure_ascii=False) if out[key] is not None else ""
        out.setdefault("kind", "fact")
        return out


